from scipy.optimize import least_squares
def model(p,t,P):
    r,K,c0,c1,w,ph,c2=p
    return r*P*(1-P/K)+c0+c1*np.sin(w*t+ph)+c2*t
best=None
for w0 in np.linspace(0.1,3,30):
    for ph0 in [0,1.5,3]:
        try:
            res=least_squares(lambda p: model(p,t,P)-dP_dt,[2.5,10,6,2,w0,ph0,0],max_nfev=2000)
            if best is None or res.cost<best.cost: best=res
        except Exception: pass
print(np.round(best.x,4), np.mean(best.fun**2)/np.var(dP_dt))

Pf={'1':np.ones_like(P),'P':P,'P2':P**2,'sqP':np.sqrt(P),'PlnP':P*np.log(P),'lnP':np.log(P),'P3':P**3}
tf={'1':np.ones_like(t),'t':t,'t2':t**2,'st':np.sqrt(t),'lt':np.log(t),'et':np.exp(-t),'Pt':None}
cols=[];names=[]
for a,pa in Pf.items():
    for b,tb in tf.items():
        if tb is None: continue
        cols.append(pa*tb); names.append(a+'*'+b)
A=np.column_stack(cols)
c,_,_,_=lstsq(A,dP_dt,rcond=None); r=dP_dt-A@c
print('NMSE',np.mean(r**2)/np.var(dP_dt))
# greedy backward elimination
keep=list(range(len(cols)))
while len(keep)>1:
    best=None
    for k in keep:
        kk=[j for j in keep if j!=k]
        cc,_,_,_=lstsq(A[:,kk],dP_dt,rcond=None); rr=dP_dt-A[:,kk]@cc
        e=np.mean(rr**2)/np.var(dP_dt)
        if best is None or e<best[0]: best=(e,k)
    keep=[j for j in keep if j!=best[1]]
    if best[0]>1e-3: break
    print(round(best[0],8),[names[j] for j in keep])

